<script>document.querySelectorAll('.thread').forEach(t=>t.onclick=()=>{document.querySelectorAll('.thread').forEach(x=>x.classList.remove('selected'));t.classList.add('selected');document.getElementById('conversationTitle').textContent=t.dataset.tracking;document.getElementById('conversationMeta').textContent=t.dataset.phone;document.getElementById('conversationMessages').innerHTML='<div class="message out">'+atob(t.dataset.message).replace(/</g,'&lt;')+'<small>'+t.dataset.meta+'</small></div>'});document.querySelectorAll('.chat-tab').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('.chat-tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active');const campaigns=tab.dataset.tab==='campaigns';document.getElementById('campaignsTab').style.display=campaigns?'block':'none';document.getElementById('personalTab').style.display=campaigns?'none':'block'});</script>
